CREATE OR REPLACE FUNCTION public.platform_assign_org_to_group(p_group_id uuid, p_org_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_group_status TEXT;
    v_org_id UUID;
BEGIN
    SET LOCAL row_security = off;

    SELECT status INTO v_group_status
    FROM groups
    WHERE id = p_group_id;
    IF v_group_status IS NULL THEN
        SET LOCAL row_security = on;
        RETURN NULL;
    END IF;
    IF v_group_status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'group % is not active', p_group_id
            USING ERRCODE = '23514';
    END IF;

    SELECT id INTO v_org_id
    FROM organizations
    WHERE id = p_org_id
      AND id <> '00000000-0000-0000-0000-00000000face'::uuid;
    IF v_org_id IS NULL THEN
        SET LOCAL row_security = on;
        RETURN NULL;
    END IF;

    INSERT INTO group_memberships (group_id, org_id)
    VALUES (p_group_id, p_org_id)
    ON CONFLICT (org_id) DO UPDATE
        SET group_id = EXCLUDED.group_id,
            created_at = now();

    UPDATE organizations
    SET group_id = p_group_id,
        updated_at = now()
    WHERE id = p_org_id;

    SET LOCAL row_security = on;
    RETURN p_org_id;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_attach_group_of_one(p_org_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_row_security TEXT := current_setting('row_security');
    v_org organizations%ROWTYPE;
    v_group_id UUID;
BEGIN
    SET LOCAL row_security = off;

    SELECT * INTO v_org FROM organizations WHERE id = p_org_id;
    IF v_org.id IS NULL THEN
        PERFORM set_config('row_security', v_row_security, true);
        RAISE EXCEPTION 'organization % not found', p_org_id USING ERRCODE = '23503';
    END IF;

    v_group_id := platform_mint_group_row(p_org_id, v_org.name, v_org.status);

    UPDATE organizations
       SET group_id = v_group_id, updated_at = now()
     WHERE id = p_org_id;

    PERFORM platform_attach_membership(v_group_id, p_org_id);

    PERFORM set_config('row_security', v_row_security, true);
    RETURN v_group_id;
EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('row_security', v_row_security, true);
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_create_group(p_slug text, p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_id UUID;
BEGIN
    SET LOCAL row_security = off;

    INSERT INTO groups (slug, name)
    VALUES (btrim(p_slug), btrim(p_name))
    RETURNING id INTO v_id;

    SET LOCAL row_security = on;
    RETURN v_id;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_create_group_account(p_group_id uuid, p_org_id uuid, p_display_name text, p_phone text DEFAULT NULL::text, p_tenant_roles text[] DEFAULT ARRAY['MEMBER'::text], p_group_role text DEFAULT 'GROUP_ADMIN'::text, p_granted_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_group_status TEXT;
    v_org_id UUID;
    v_user_id UUID;
    v_roles TEXT[] := COALESCE(p_tenant_roles, ARRAY['MEMBER']::TEXT[]);
BEGIN
    SET LOCAL row_security = off;

    SELECT status INTO v_group_status
    FROM groups
    WHERE id = p_group_id;
    IF v_group_status IS NULL THEN
        SET LOCAL row_security = on;
        RETURN NULL;
    END IF;
    IF v_group_status <> 'ACTIVE' THEN
        RAISE EXCEPTION 'group % is not active', p_group_id
            USING ERRCODE = '23514';
    END IF;

    SELECT o.id INTO v_org_id
    FROM organizations o
    JOIN group_memberships gm
      ON gm.org_id = o.id
     AND gm.group_id = p_group_id
    WHERE o.id = p_org_id
      AND o.status = 'ACTIVE'
      AND o.id <> '00000000-0000-0000-0000-00000000face'::uuid;
    IF v_org_id IS NULL THEN
        SET LOCAL row_security = on;
        RETURN NULL;
    END IF;

    IF NULLIF(btrim(p_display_name), '') IS NULL THEN
        RAISE EXCEPTION 'display_name is required'
            USING ERRCODE = '23514';
    END IF;
    IF cardinality(v_roles) = 0 THEN
        RAISE EXCEPTION 'tenant role is required'
            USING ERRCODE = '23514';
    END IF;

    PERFORM set_config('app.current_org', p_org_id::text, true);

    INSERT INTO users (display_name, phone, roles, is_active, org_id)
    VALUES (
        btrim(p_display_name),
        NULLIF(btrim(p_phone), ''),
        v_roles,
        true,
        p_org_id
    )
    RETURNING id INTO v_user_id;

    INSERT INTO group_role_grants (group_id, user_id, group_role, granted_by)
    VALUES (p_group_id, v_user_id, p_group_role, p_granted_by);

    SET LOCAL row_security = on;
    RETURN v_user_id;
EXCEPTION WHEN OTHERS THEN
    SET LOCAL row_security = on;
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_force_remove_organization(p_id uuid)
